B.a22=s([B.fM,B.QT,B.Qy,B.Qk,B.uI,B.fN,B.fO,B.fP],t.gk)
B.abC=new A.uX("folder_memberships",B.a22)
B.Qj=new A.cP("from_id",B.aH)
B.QU=new A.cP("to_id",B.aH)
B.a2w=s([B.fM,B.Qj,B.QU,B.uG,B.fN,B.fO,B.fP],t.gk)
B.abE=new A.uX("item_links",B.a2w)
B.a2k=s([B.fM,B.fN,B.fO,B.fP],t.gk)
B.abB=new A.uX("inbox_dismissals",B.a2k)
B.lE=s([B.abD,B.abz,B.abA,B.abC,B.abE,B.abB],t.la)
B.Tq=new A.G2("/database",0,"database")
B.Tr=new A.G2("/database-journal",1,"journal")
B.xe=s([B.Tq,B.Tr],A.ae("A<G2>"))
